"use client";

import { useMemo, useState } from "react";
import { cn } from "@/lib/cn";

interface Point {
  date: string; // ISO
  count: number;
}

interface Props {
  data: Point[];
  weeks?: number;
}

/**
 * Minimal SVG submission heatmap. Monochrome ramp of five steps — no
 * `react-calendar-heatmap` dependency needed.
 */
export function SubmissionHeatmap({ data, weeks = 30 }: Props) {
  const buckets = useMemo(() => {
    const map = new Map<string, number>();
    for (const p of data) map.set(p.date, p.count);
    const today = new Date();
    // Snap to Sunday of current week.
    today.setDate(today.getDate() - today.getDay());
    const cells: { date: string; count: number }[] = [];
    for (let w = weeks - 1; w >= 0; w--) {
      for (let d = 0; d < 7; d++) {
        const dt = new Date(today);
        dt.setDate(dt.getDate() - w * 7 + d);
        const iso = dt.toISOString().slice(0, 10);
        cells.push({ date: iso, count: map.get(iso) ?? 0 });
      }
    }
    return cells;
  }, [data, weeks]);

  const [hover, setHover] = useState<{
    x: number;
    y: number;
    label: string;
  } | null>(null);

  const CELL = 12;
  const GAP = 3;
  const width = weeks * (CELL + GAP);
  const height = 7 * (CELL + GAP);

  const step = (count: number): 0 | 1 | 2 | 3 | 4 => {
    if (count === 0) return 0;
    if (count < 2) return 1;
    if (count < 4) return 2;
    if (count < 6) return 3;
    return 4;
  };
  const cls: Record<0 | 1 | 2 | 3 | 4, string> = {
    0: "fill-neutral-100",
    1: "fill-neutral-300",
    2: "fill-neutral-500",
    3: "fill-neutral-700",
    4: "fill-neutral-950",
  };

  return (
    <div className="relative">
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full"
        role="img"
        aria-label="Submission heatmap"
      >
        {buckets.map((c, i) => {
          const w = Math.floor(i / 7);
          const d = i % 7;
          const x = w * (CELL + GAP);
          const y = d * (CELL + GAP);
          return (
            <rect
              key={c.date}
              x={x}
              y={y}
              width={CELL}
              height={CELL}
              rx={2}
              className={cn(cls[step(c.count)], "transition-colors")}
              onMouseEnter={() =>
                setHover({
                  x: x + CELL / 2,
                  y: y,
                  label: `${c.count} on ${c.date}`,
                })
              }
              onMouseLeave={() => setHover(null)}
            />
          );
        })}
      </svg>
      {hover ? (
        <div
          className="pointer-events-none absolute -translate-x-1/2 -translate-y-full rounded-md bg-neutral-950 px-2 py-1 text-[11px] font-medium text-white"
          style={{
            left: `${(hover.x / width) * 100}%`,
            top: `${(hover.y / height) * 100}%`,
          }}
        >
          {hover.label}
        </div>
      ) : null}
      <div className="mt-2 flex items-center justify-end gap-1.5 text-[10.5px] text-neutral-500">
        Less
        {[0, 1, 2, 3, 4].map((s) => (
          <span
            key={s}
            className={cn(
              "h-2.5 w-2.5 rounded-[2px]",
              cls[s as 0 | 1 | 2 | 3 | 4].replace("fill-", "bg-"),
            )}
          />
        ))}
        More
      </div>
    </div>
  );
}
